class NativeShutdownLockBarrierTest {

	private static final long INITIAL_MAP_SIZE = 8L * 1024 * 1024;

	@Test
	void transactionManagerCloseWaitsForNativeReadLock(@TempDir Path directory) throws Exception {
		long environment = openEnvironment(directory);
		TxnManager txnManager = new TxnManager(environment, Mode.RESET);
		TxnManager.Txn reader = txnManager.createReadTxn();
		CountDownLatch closedWhileReadActive = new CountDownLatch(1);
		try {
			assertShutdownWaitsForReadLock(txnManager.lockManager(), () -> {
				txnManager.close();
				if (reader.isClosed() && txnManager.lockManager().isReaderActive()) {
					closedWhileReadActive.countDown();
				}
			}, closedWhileReadActive);
		} finally {
			reader.close();
			txnManager.close();
			mdb_env_close(environment);
		}
	}

	@Test
	void valueStoreCloseWaitsForNativeReadLock(@TempDir Path directory) throws Exception {
		CountDownLatch environmentClosedWhileReadActive = new CountDownLatch(1);
		ValueStore store = new ReadLockObservingValueStore(directory.resolve("values"),
				new LmdbStoreConfig().setValueDBSize(INITIAL_MAP_SIZE), environmentClosedWhileReadActive);
		try {
			assertShutdownWaitsForReadLock(store.getTxnManager().lockManager(), store::close,
					environmentClosedWhileReadActive);
		} finally {
			store.close();
		}
	}

	@Test
	void tripleStoreCloseWaitsForNativeReadLock(@TempDir Path directory) throws Exception {
		CountDownLatch environmentClosedWhileReadActive = new CountDownLatch(1);
		AtomicReference<StampedLongAdderLockManager> lockManager = new AtomicReference<>();
		TripleStore.EnvironmentLifecycle lifecycle = new TripleStore.EnvironmentLifecycle() {
			@Override
			public void afterOpen(long env) {
			}

			@Override
			public void close(long env) {
				StampedLongAdderLockManager manager = lockManager.get();
				if (manager != null && manager.isReaderActive()) {
					environmentClosedWhileReadActive.countDown();
				}
				mdb_env_close(env);
			}
		};
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(INITIAL_MAP_SIZE)
				.setPageCardinalityEstimator(false);
		TripleStore store = new TripleStore(directory.toFile(), new StoreProperties(directory.toFile()), config, null,
				lifecycle);
		lockManager.set(store.getTxnManager().lockManager());
		try {
			assertShutdownWaitsForReadLock(lockManager.get(), store::close, environmentClosedWhileReadActive);
		} finally {
			store.close();
		}
	}

	private static void assertShutdownWaitsForReadLock(StampedLongAdderLockManager lockManager, CloseAction close,
			CountDownLatch closedWhileReadActive) throws Exception {
		long readStamp = lockManager.readLock();
		CountDownLatch closeStarted = new CountDownLatch(1);
		CountDownLatch closeFinished = new CountDownLatch(1);
		AtomicReference<Throwable> closeFailure = new AtomicReference<>();
		Thread closer = new Thread(() -> {
			closeStarted.countDown();
			try {
				close.close();
			} catch (Throwable failure) {
				closeFailure.set(failure);
			} finally {
				closeFinished.countDown();
			}
		}, "lmdb-shutdown-lock-barrier-test");
		closer.setDaemon(true);
		try {
			closer.start();
			assertTrue(closeStarted.await(5, TimeUnit.SECONDS), "shutdown thread must start");
			awaitSignal(() -> lockManager.isWriterActive() || closedWhileReadActive.getCount() == 0
					|| closeFinished.getCount() == 0,
					"shutdown must either wait at the native writer barrier or reveal an early close");
			assertEquals(1L, closedWhileReadActive.getCount(),
					"shutdown must not close the native environment while a native read interval is active");
			assertEquals(1L, closeFinished.getCount(),
					"shutdown must remain blocked until the native read interval ends");
		} finally {
			lockManager.unlockRead(readStamp);
			closer.join(TimeUnit.SECONDS.toMillis(5));
		}
		assertFalse(closer.isAlive(), "shutdown must complete after the native read interval ends");
		assertNull(closeFailure.get(), () -> "shutdown failed: " + closeFailure.get());
	}

	private static void awaitSignal(BooleanSupplier condition, String message) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		boolean signalled = condition.getAsBoolean();
		while (!signalled && System.nanoTime() - deadline < 0) {
			Thread.yield();
			signalled = condition.getAsBoolean();
		}
		assertTrue(signalled, message);
	}

	private static long openEnvironment(Path directory) throws IOException {
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_env_create(pointer));
			long environment = pointer.get(0);
			E(mdb_env_set_maxreaders(environment, TxnManager.POOL_SIZE));
			E(mdb_env_open(environment, directory.toAbsolutePath().toString(),
					MDB_NOTLS | MDB_NOSYNC | MDB_NOMETASYNC, 0664));
			return environment;
		}
	}

	@FunctionalInterface
	private interface CloseAction {
		void close() throws Exception;
	}

	private static final class ReadLockObservingValueStore extends ValueStore {
		private final CountDownLatch environmentClosedWhileReadActive;

		private ReadLockObservingValueStore(Path directory, LmdbStoreConfig config,
				CountDownLatch environmentClosedWhileReadActive) throws IOException {
			super(directory.toFile(), config);
			this.environmentClosedWhileReadActive = environmentClosedWhileReadActive;
		}

		@Override
		void closeEnvironment(long environment) {
			TxnManager manager = getTxnManager();
			if (manager != null && manager.lockManager().isReaderActive()) {
				environmentClosedWhileReadActive.countDown();
			}
			super.closeEnvironment(environment);
		}
	}
}
